package edu.swarmintelligence.mayfly;

import java.util.LinkedHashMap;
import java.util.Map;

public class AgentInteractionAnalyzer implements MayflyAnalyzer {

    private static final String NUPTIAL_DANCE = "NUPTIAL_DANCE";
    private static final String MALE_ATTRACTION = "MALE_ATTRACTION";
    private static final String FEMALE_ATTRACTION = "FEMALE_ATTRACTION";
    private static final String FEMALE_RANDOM_WALK = "FEMALE_RANDOM_WALK";

    private int currentIteration;

    private int nuptialDanceCount;
    private int attractionCount;

    private int femaleUpdatesInIteration;
    private int femaleAttractionsInIteration;
    private double pairDistanceSumInIteration;
    private double pairFitnessGapSumInIteration;

    private final Map<Integer, Double> femaleAttractionRate = new LinkedHashMap<>();
    private final Map<Integer, Double> meanPairDistance = new LinkedHashMap<>();
    private final Map<Integer, Double> pairFitnessGap = new LinkedHashMap<>();
    private final Map<String, Integer> interactionHistogram = new LinkedHashMap<>();

    public AgentInteractionAnalyzer() {
        interactionHistogram.put(NUPTIAL_DANCE, 0);
        interactionHistogram.put(MALE_ATTRACTION, 0);
        interactionHistogram.put(FEMALE_ATTRACTION, 0);
        interactionHistogram.put(FEMALE_RANDOM_WALK, 0);
    }

    @Override
    public String name() {
        return "agent-interaction";
    }

    @Override
    public void onEvent(MayflyEvent event) {
        switch (event) {
            case MayflyEvent.IterationStarted started -> handleIterationStarted(started);
            case MayflyEvent.MaleUpdated maleUpdated -> handleMaleUpdated(maleUpdated);
            case MayflyEvent.FemaleUpdated femaleUpdated -> handleFemaleUpdated(femaleUpdated);
            case MayflyEvent.IterationCompleted completed -> handleIterationCompleted(completed);
            default -> {
                // Other event types are not relevant for this analyzer.
            }
        }
    }

    @Override
    public AnalyzerResult result() {
        return new AgentInteractionResult(
                nuptialDanceCount,
                attractionCount,
                femaleAttractionRate,
                meanPairDistance,
                pairFitnessGap,
                interactionHistogram
        );
    }

    private void handleIterationStarted(MayflyEvent.IterationStarted event) {
        currentIteration = event.iteration();

        femaleUpdatesInIteration = 0;
        femaleAttractionsInIteration = 0;
        pairDistanceSumInIteration = 0.0;
        pairFitnessGapSumInIteration = 0.0;
    }

    private void handleMaleUpdated(MayflyEvent.MaleUpdated event) {
        if (event.isNuptialDance()) {
            nuptialDanceCount++;
            incrementHistogram(NUPTIAL_DANCE);
        } else {
            attractionCount++;
            incrementHistogram(MALE_ATTRACTION);
        }
    }

    private void handleFemaleUpdated(MayflyEvent.FemaleUpdated event) {
        femaleUpdatesInIteration++;

        if (event.isAttracted()) {
            femaleAttractionsInIteration++;
            incrementHistogram(FEMALE_ATTRACTION);
        } else {
            incrementHistogram(FEMALE_RANDOM_WALK);
        }

        pairDistanceSumInIteration += euclideanDistance(
                event.agent().pos,
                event.pairedMale().pos
        );

        pairFitnessGapSumInIteration += Math.abs(
                event.agent().fitness - event.pairedMale().fitness
        );
    }

    private void handleIterationCompleted(MayflyEvent.IterationCompleted event) {
        if (femaleUpdatesInIteration == 0) {
            femaleAttractionRate.put(currentIteration, 0.0);
            meanPairDistance.put(currentIteration, 0.0);
            pairFitnessGap.put(currentIteration, 0.0);
            return;
        }

        femaleAttractionRate.put(
                currentIteration,
                (double) femaleAttractionsInIteration / femaleUpdatesInIteration
        );

        meanPairDistance.put(
                currentIteration,
                pairDistanceSumInIteration / femaleUpdatesInIteration
        );

        pairFitnessGap.put(
                currentIteration,
                pairFitnessGapSumInIteration / femaleUpdatesInIteration
        );
    }

    private void incrementHistogram(String key) {
        interactionHistogram.merge(key, 1, Integer::sum);
    }

    private double euclideanDistance(double[] a, double[] b) {
        double sum = 0.0;

        for (int i = 0; i < a.length; i++) {
            double diff = a[i] - b[i];
            sum += diff * diff;
        }

        return Math.sqrt(sum);
    }
}

