package edu.swarmintelligence.mayfly;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.random.RandomGenerator;
import java.util.random.RandomGeneratorFactory;

public class MayflyAlgorithm {

    private final List<MayflyEventListener> listeners = new ArrayList<>();

    public void addListener(MayflyEventListener listener) {
        if (listener == null) {
            throw new IllegalArgumentException("listener must not be null");
        }
        listeners.add(listener);
    }

    private void fire(MayflyEvent event) {
        for (MayflyEventListener listener : listeners) {
            listener.onEvent(event);
        }
    }

    /**
     * Runs the algorithm and returns the best position and fitness found.
     */
    public MayflyResult run(MayflyConfig cfg, long seed) {
        RandomGenerator rng = RandomGeneratorFactory.of("Xoshiro256PlusPlus").create(seed);
        RunState state = new RunState(cfg.dimensions());

        List<Mayfly> males = initializePopulation(cfg, rng);
        List<Mayfly> females = initializePopulation(cfg, rng);

        // Synchronous global best from initial populations.
        // No GbestUpdated event is fired here, because initialization is not part of the iteration loop.
        males.forEach(m -> updateInitialGlobalBest(cfg, state, m.fitness, m.pos));
        females.forEach(f -> updateInitialGlobalBest(cfg, state, f.fitness, f.pos));

        Comparator<Mayfly> byFitness = Comparator.comparingDouble(m -> m.fitness);

        for (int iter = 1; iter <= cfg.maxIterations(); iter++) {
            double w = inertiaWeight(cfg, iter);

            fire(new MayflyEvent.IterationStarted(iter, w));

            // ----- 1. Male movement (synchronous) -----
            moveMales(cfg, rng, state, males, w);

            // Re-rank males for female movement and mating
            List<Mayfly> sortedMales = sortByFitness(males);

            // ----- 2. Female movement (synchronous) -----
            moveFemales(cfg, rng, state, females, sortedMales, w);

            // Re-sort both populations after female movement
            sortedMales = sortByFitness(males);
            List<Mayfly> sortedFemales = sortByFitness(females);

            // ----- 3. Mating -----
            List<Mayfly> offspring = mate(cfg, rng, state, sortedMales, sortedFemales);

            // ----- 4. Global selection (Zervoudakis & Tsafarakis) -----
            List<Mayfly> pool = new ArrayList<>(cfg.populationSize() * 4);
            pool.addAll(males);
            pool.addAll(females);
            pool.addAll(offspring);
            pool.sort(byFitness);

            List<Mayfly> survivors = new ArrayList<>(pool.subList(0, 2 * cfg.populationSize()));

            males = new ArrayList<>(pool.subList(0, cfg.populationSize()));
            females = new ArrayList<>(pool.subList(cfg.populationSize(), 2 * cfg.populationSize()));

            fire(new MayflyEvent.IterationCompleted(
                    iter,
                    state.gbestFitness,
                    survivors
            ));
        }

        MayflyResult result = new MayflyResult(state.gbestPosition, state.gbestFitness);
        fire(new MayflyEvent.RunCompleted(result));

        return result;
    }

    // ---------- Run State ----------
    private static final class RunState {
        private final double[] gbestPosition;
        private double gbestFitness = Double.POSITIVE_INFINITY;

        private RunState(int dimensions) {
            this.gbestPosition = new double[dimensions];
        }
    }

    // ---------- Initialization ----------
    private List<Mayfly> initializePopulation(MayflyConfig cfg, RandomGenerator rng) {
        List<Mayfly> pop = new ArrayList<>(cfg.populationSize());

        for (int i = 0; i < cfg.populationSize(); i++) {
            Mayfly m = new Mayfly(cfg.dimensions());

            for (int d = 0; d < cfg.dimensions(); d++) {
                m.pos[d] = rng.nextDouble(cfg.lowerBound(), cfg.upperBound());
            }

            m.fitness = evaluate(cfg, m.pos);
            m.updatePersonalBest();
            pop.add(m);
        }

        return pop;
    }

    // ---------- Movement ----------
    private void moveMales(
            MayflyConfig cfg,
            RandomGenerator rng,
            RunState state,
            List<Mayfly> males,
            double w
    ) {
        Mayfly bestMale = males.stream()
                .min(Comparator.comparingDouble(m -> m.fitness))
                .orElseThrow();

        double[][] newPos = new double[males.size()][cfg.dimensions()];
        double[][] newVel = new double[males.size()][cfg.dimensions()];

        for (int i = 0; i < males.size(); i++) {
            Mayfly male = males.get(i);
            double dP2 = squaredDistance(male.pos, male.pbestPos);
            double dG2 = squaredDistance(male.pos, state.gbestPosition);

            for (int d = 0; d < cfg.dimensions(); d++) {
                double vel;

                if (male == bestMale) {
                    vel = w * male.vel[d]
                            + cfg.danceCoeff() * rng.nextDouble(-1.0, 1.0);
                } else {
                    vel = w * male.vel[d]
                            + cfg.a1() * Math.exp(-cfg.beta() * dP2) * (male.pbestPos[d] - male.pos[d])
                            + cfg.a2() * Math.exp(-cfg.beta() * dG2) * (state.gbestPosition[d] - male.pos[d]);
                }

                newVel[i][d] = vel;
                newPos[i][d] = clamp(cfg, male.pos[d] + vel);
            }
        }

        for (int i = 0; i < males.size(); i++) {
            Mayfly male = males.get(i);

            double previousFitness = male.fitness;
            double previousPbestFitness = male.pbestFitness;
            boolean isNuptialDance = male == bestMale;

            System.arraycopy(newPos[i], 0, male.pos, 0, cfg.dimensions());
            System.arraycopy(newVel[i], 0, male.vel, 0, cfg.dimensions());

            male.fitness = evaluate(cfg, male.pos);
            male.updatePersonalBest();

            fire(new MayflyEvent.MaleUpdated(
                    male,
                    isNuptialDance,
                    previousFitness
            ));

            firePbestUpdatedIfNecessary(male, previousPbestFitness);

            updateGlobalBest(
                    cfg,
                    state,
                    UpdateSource.MALE,
                    male.fitness,
                    male.pos
            );
        }
    }

    private void moveFemales(
            MayflyConfig cfg,
            RandomGenerator rng,
            RunState state,
            List<Mayfly> females,
            List<Mayfly> sortedMales,
            double w
    ) {
        List<Mayfly> sortedFemales = sortByFitness(females);

        double[][] newPos = new double[cfg.populationSize()][cfg.dimensions()];
        double[][] newVel = new double[cfg.populationSize()][cfg.dimensions()];
        boolean[] attractedFlags = new boolean[cfg.populationSize()];
        Mayfly[] pairedMales = new Mayfly[cfg.populationSize()];

        for (int i = 0; i < cfg.populationSize(); i++) {
            Mayfly female = sortedFemales.get(i);
            Mayfly male = sortedMales.get(i);
            boolean attracted = male.fitness < female.fitness;

            attractedFlags[i] = attracted;
            pairedMales[i] = male;

            double dMF2 = attracted ? squaredDistance(female.pos, male.pos) : 0;

            for (int d = 0; d < cfg.dimensions(); d++) {
                double vel;

                if (attracted) {
                    vel = w * female.vel[d]
                            + cfg.a3() * Math.exp(-cfg.beta() * dMF2) * (male.pos[d] - female.pos[d]);
                } else {
                    vel = w * female.vel[d]
                            + cfg.flightCoeff() * rng.nextDouble(-1.0, 1.0);
                }

                newVel[i][d] = vel;
                newPos[i][d] = clamp(cfg, female.pos[d] + vel);
            }
        }

        for (int i = 0; i < cfg.populationSize(); i++) {
            Mayfly female = sortedFemales.get(i);

            double previousFitness = female.fitness;
            double previousPbestFitness = female.pbestFitness;

            System.arraycopy(newPos[i], 0, female.pos, 0, cfg.dimensions());
            System.arraycopy(newVel[i], 0, female.vel, 0, cfg.dimensions());

            female.fitness = evaluate(cfg, female.pos);
            female.updatePersonalBest();

            fire(new MayflyEvent.FemaleUpdated(
                    female,
                    pairedMales[i],
                    attractedFlags[i],
                    previousFitness
            ));

            firePbestUpdatedIfNecessary(female, previousPbestFitness);

            updateGlobalBest(
                    cfg,
                    state,
                    UpdateSource.FEMALE,
                    female.fitness,
                    female.pos
            );
        }
    }

    // ---------- Mating ----------
    private List<Mayfly> mate(
            MayflyConfig cfg,
            RandomGenerator rng,
            RunState state,
            List<Mayfly> sortedMales,
            List<Mayfly> sortedFemales
    ) {
        List<Mayfly> offspring = new ArrayList<>(cfg.populationSize() * 2);

        for (int i = 0; i < cfg.populationSize(); i++) {
            Mayfly p1 = sortedMales.get(i);
            Mayfly p2 = sortedFemales.get(i);
            double l = rng.nextDouble();

            Mayfly child1 = new Mayfly(cfg.dimensions());
            Mayfly child2 = new Mayfly(cfg.dimensions());

            for (int d = 0; d < cfg.dimensions(); d++) {
                child1.pos[d] = l * p1.pos[d] + (1.0 - l) * p2.pos[d];
                child2.pos[d] = l * p2.pos[d] + (1.0 - l) * p1.pos[d];
            }

            applyMutation(cfg, rng, child1);
            applyMutation(cfg, rng, child2);

            fire(new MayflyEvent.OffspringCreated(child1));
            fire(new MayflyEvent.OffspringCreated(child2));

            updateGlobalBest(
                    cfg,
                    state,
                    UpdateSource.OFFSPRING,
                    child1.fitness,
                    child1.pos
            );
            updateGlobalBest(
                    cfg,
                    state,
                    UpdateSource.OFFSPRING,
                    child2.fitness,
                    child2.pos
            );

            offspring.add(child1);
            offspring.add(child2);
        }

        return offspring;
    }

    private void applyMutation(MayflyConfig cfg, RandomGenerator rng, Mayfly m) {
        for (int d = 0; d < cfg.dimensions(); d++) {
            m.pos[d] += rng.nextGaussian() * cfg.mutationStdDev();
            m.pos[d] = clamp(cfg, m.pos[d]);
        }

        m.fitness = evaluate(cfg, m.pos);

        double previousPbestFitness = m.pbestFitness;
        m.updatePersonalBest();
        firePbestUpdatedIfNecessary(m, previousPbestFitness);
    }

    // ---------- Helpers ----------
    private double inertiaWeight(MayflyConfig cfg, int iter) {
        return cfg.wMax()
                - (cfg.wMax() - cfg.wMin()) * ((double) iter / cfg.maxIterations());
    }

    private double clamp(MayflyConfig cfg, double value) {
        return Math.clamp(value, cfg.lowerBound(), cfg.upperBound());
    }

    private double squaredDistance(double[] a, double[] b) {
        double sum = 0;

        for (int i = 0; i < a.length; i++) {
            double diff = a[i] - b[i];
            sum += diff * diff;
        }

        return sum;
    }

    private double evaluate(MayflyConfig cfg, double[] x) {
        double s1 = 0;
        double s2 = 0;

        for (double v : x) {
            s1 += v * v;
            s2 += Math.cos(2 * Math.PI * v);
        }

        return -20.0 * Math.exp(-0.2 * Math.sqrt(s1 / cfg.dimensions()))
                - Math.exp(s2 / cfg.dimensions())
                + 20.0
                + Math.E;
    }

    private void updateInitialGlobalBest(MayflyConfig cfg, RunState state, double fitness, double[] pos) {
        if (fitness < state.gbestFitness) {
            state.gbestFitness = fitness;
            System.arraycopy(pos, 0, state.gbestPosition, 0, cfg.dimensions());
        }
    }

    private void updateGlobalBest(
            MayflyConfig cfg,
            RunState state,
            UpdateSource source,
            double fitness,
            double[] pos
    ) {
        if (fitness < state.gbestFitness) {
            double previousGbestFitness = state.gbestFitness;

            state.gbestFitness = fitness;
            System.arraycopy(pos, 0, state.gbestPosition, 0, cfg.dimensions());

            fire(new MayflyEvent.GbestUpdated(
                    source,
                    previousGbestFitness,
                    state.gbestFitness
            ));
        }
    }

    private void firePbestUpdatedIfNecessary(Mayfly agent, double previousPbestFitness) {
        if (agent.pbestFitness < previousPbestFitness) {
            fire(new MayflyEvent.PbestUpdated(
                    agent,
                    previousPbestFitness,
                    agent.pbestFitness
            ));
        }
    }

    private List<Mayfly> sortByFitness(List<Mayfly> list) {
        return list.stream()
                .sorted(Comparator.comparingDouble(m -> m.fitness))
                .toList();
    }
}

package edu.swarmintelligence.mayfly;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class GlobalMemoryAnalyzer implements MayflyAnalyzer {

    private int currentIteration;
    private boolean gbestUpdatedInCurrentIteration;
    private int currentStagnationLength;

    private final List<Double> gbestTrajectory = new ArrayList<>();
    private final Map<Integer, Double> improvementDelta = new LinkedHashMap<>();
    private final List<Integer> stagnationStreaks = new ArrayList<>();
    private final Map<UpdateSource, Integer> updateCountsBySource = new EnumMap<>(UpdateSource.class);

    private int gbestUpdateCount;

    public GlobalMemoryAnalyzer() {
        for (UpdateSource source : UpdateSource.values()) {
            updateCountsBySource.put(source, 0);
        }
    }

    @Override
    public String name() {
        return "global-memory";
    }

    @Override
    public void onEvent(MayflyEvent event) {
        switch (event) {
            case MayflyEvent.IterationStarted started -> handleIterationStarted(started);
            case MayflyEvent.GbestUpdated updated -> handleGbestUpdated(updated);
            case MayflyEvent.IterationCompleted completed -> handleIterationCompleted(completed);
            case MayflyEvent.RunCompleted completed -> handleRunCompleted();
            default -> {
                // Other event types are not relevant for this analyzer.
            }
        }
    }

    @Override
    public AnalyzerResult result() {
        return new GlobalMemoryResult(
                gbestTrajectory,
                gbestUpdateCount,
                sourceDistribution(),
                improvementDelta,
                stagnationStreaks
        );
    }

    private void handleIterationStarted(MayflyEvent.IterationStarted event) {
        currentIteration = event.iteration();
        gbestUpdatedInCurrentIteration = false;
        improvementDelta.put(currentIteration, 0.0);
    }

    private void handleGbestUpdated(MayflyEvent.GbestUpdated event) {
        gbestUpdateCount++;
        gbestUpdatedInCurrentIteration = true;

        updateCountsBySource.merge(event.source(), 1, Integer::sum);

        double delta = event.previousGbestFitness() - event.newGbestFitness();

        if (Double.isFinite(delta) && delta > 0.0) {
            improvementDelta.merge(currentIteration, delta, Double::sum);
        }
    }

    private void handleIterationCompleted(MayflyEvent.IterationCompleted event) {
        gbestTrajectory.add(event.gbestFitness());

        if (gbestUpdatedInCurrentIteration) {
            closeCurrentStagnationIfNecessary();
        } else {
            currentStagnationLength++;
        }
    }

    private void handleRunCompleted() {
        closeCurrentStagnationIfNecessary();
    }

    private void closeCurrentStagnationIfNecessary() {
        if (currentStagnationLength > 0) {
            stagnationStreaks.add(currentStagnationLength);
            currentStagnationLength = 0;
        }
    }

    private Map<UpdateSource, Double> sourceDistribution() {
        Map<UpdateSource, Double> distribution = new LinkedHashMap<>();

        if (gbestUpdateCount == 0) {
            for (UpdateSource source : UpdateSource.values()) {
                distribution.put(source, 0.0);
            }

            return distribution;
        }

        for (UpdateSource source : UpdateSource.values()) {
            int count = updateCountsBySource.getOrDefault(source, 0);
            distribution.put(source, (double) count / gbestUpdateCount);
        }

        return distribution;
    }
}

package edu.swarmintelligence.mayfly;

