        int gbestUpdateCount,
        Map<UpdateSource, Double> gbestUpdateSourceDistribution,
        Map<Integer, Double> improvementDelta,
        List<Integer> stagnationStreaks
) implements AnalyzerResult {

    public GlobalMemoryResult {
        gbestTrajectory = List.copyOf(gbestTrajectory);
        gbestUpdateSourceDistribution = Collections.unmodifiableMap(
                new LinkedHashMap<>(gbestUpdateSourceDistribution)
        );
        improvementDelta = Collections.unmodifiableMap(
                new LinkedHashMap<>(improvementDelta)
        );
        stagnationStreaks = List.copyOf(stagnationStreaks);
    }

    public int firstHittingIteration(double epsilon) {
        for (int i = 0; i < gbestTrajectory.size(); i++) {
            if (gbestTrajectory.get(i) <= epsilon) {
                return i + 1;
            }
        }

        return -1;
    }
}

