package edu.swarmintelligence.mayfly;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class ConvergenceAnalyzer implements MayflyAnalyzer {

    private static final int DEFAULT_PLATEAU_MIN_LENGTH = 5;
    private static final double DEFAULT_PLATEAU_EPSILON = 1e-12;
    private static final double DEFAULT_FIT_PERCENTAGE = 0.20;

    private final int plateauMinLength;
    private final double plateauEpsilon;
    private final double fitPercentage;

    private final List<Double> convergenceCurve = new ArrayList<>();
    private final Map<Integer, Double> populationDiversity = new LinkedHashMap<>();
    private final List<PlateauSegment> plateauSegments = new ArrayList<>();

    private int plateauStartIteration = -1;
    private int plateauLength;
    private double previousFitness = Double.NaN;
    private int totalIterations;

    public ConvergenceAnalyzer() {
        this(DEFAULT_PLATEAU_MIN_LENGTH, DEFAULT_PLATEAU_EPSILON, DEFAULT_FIT_PERCENTAGE);
    }

    public ConvergenceAnalyzer(int plateauMinLength, double plateauEpsilon, double fitPercentage) {
        if (plateauMinLength <= 0) {
            throw new IllegalArgumentException("plateauMinLength must be greater than 0");
        }
        if (plateauEpsilon < 0.0) {
            throw new IllegalArgumentException("plateauEpsilon must not be negative");
        }
        if (fitPercentage <= 0.0 || fitPercentage > 1.0) {
            throw new IllegalArgumentException("fitPercentage must be in (0, 1]");
        }

        this.plateauMinLength = plateauMinLength;
        this.plateauEpsilon = plateauEpsilon;
        this.fitPercentage = fitPercentage;
    }

    @Override
    public String name() {
        return "convergence";
    }

    @Override
    public void onEvent(MayflyEvent event) {
        switch (event) {
            case MayflyEvent.IterationCompleted completed -> handleIterationCompleted(completed);
            case MayflyEvent.RunCompleted ignored -> closePlateauIfNecessary();
            default -> {
                // Other event types are not relevant for this analyzer.
            }
        }
    }

    @Override
    public AnalyzerResult result() {
        return new ConvergenceResult(
                convergenceCurve,
                populationDiversity,
                plateauSegments,
                convergenceRateEstimate(),
                totalIterations
        );
    }

    private void handleIterationCompleted(MayflyEvent.IterationCompleted event) {
        totalIterations = event.iteration();

        double currentFitness = event.gbestFitness();
        convergenceCurve.add(currentFitness);

        populationDiversity.put(
                event.iteration(),
                calculatePopulationDiversity(event.survivors())
        );

        updatePlateauState(event.iteration(), currentFitness);
        previousFitness = currentFitness;
    }

    private void updatePlateauState(int iteration, double currentFitness) {
        if (!Double.isFinite(previousFitness)) {
            return;
        }

        double improvement = previousFitness - currentFitness;
        boolean plateauContinues = improvement >= 0.0 && improvement <= plateauEpsilon;

        if (plateauContinues) {
            if (plateauLength == 0) {
                plateauStartIteration = iteration - 1;
            }

            plateauLength++;
        } else {
            closePlateauIfNecessary();
        }
    }

    private void closePlateauIfNecessary() {
        if (plateauLength >= plateauMinLength) {
            int endIteration = plateauStartIteration + plateauLength;

            plateauSegments.add(new PlateauSegment(
                    plateauStartIteration,
                    endIteration,
                    plateauLength + 1
            ));
        }

        plateauStartIteration = -1;
        plateauLength = 0;
    }

    private double calculatePopulationDiversity(List<Mayfly> agents) {
        if (agents.size() <= 1) {
            return 0.0;
        }

        double distanceSum = 0.0;
        int pairCount = 0;

        for (int i = 0; i < agents.size(); i++) {
            for (int j = i + 1; j < agents.size(); j++) {
                distanceSum += euclideanDistance(agents.get(i).pos, agents.get(j).pos);
                pairCount++;
            }
        }

        if (pairCount == 0) {
            return 0.0;
        }

        return distanceSum / pairCount;
    }

    private double euclideanDistance(double[] a, double[] b) {
        double sum = 0.0;

        for (int i = 0; i < a.length; i++) {
            double diff = a[i] - b[i];
            sum += diff * diff;
        }

        return Math.sqrt(sum);
    }

    private double convergenceRateEstimate() {
        if (convergenceCurve.size() < 2) {
            return 0.0;
        }

        int windowSize = Math.max(2, (int) Math.ceil(convergenceCurve.size() * fitPercentage));
        int startIndex = convergenceCurve.size() - windowSize;

        double sumX = 0.0;
        double sumY = 0.0;
        double sumXX = 0.0;
        double sumXY = 0.0;
        int count = 0;

        for (int i = startIndex; i < convergenceCurve.size(); i++) {
            double fitness = convergenceCurve.get(i);

            if (!Double.isFinite(fitness)) {
                continue;
            }

            double safeFitness = Math.max(fitness, Double.MIN_NORMAL);
            double x = i + 1;
            double y = Math.log(safeFitness);

            sumX += x;
            sumY += y;
            sumXX += x * x;
            sumXY += x * y;
            count++;
        }

        if (count < 2) {
            return 0.0;
        }

        double denominator = count * sumXX - sumX * sumX;

        if (denominator == 0.0) {
            return 0.0;
        }

        return (count * sumXY - sumX * sumY) / denominator;
    }
}

package edu.swarmintelligence.mayfly;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public record ConvergenceResult(
        List<Double> convergenceCurve,
        Map<Integer, Double> populationDiversity,
        List<PlateauSegment> plateauSegments,
        double convergenceRateEstimate,
        int totalIterations
) implements AnalyzerResult {

    public ConvergenceResult {
        convergenceCurve = List.copyOf(convergenceCurve);
        populationDiversity = Collections.unmodifiableMap(
                new LinkedHashMap<>(populationDiversity)
        );
        plateauSegments = List.copyOf(plateauSegments);
    }

    public ThresholdHit iterationsToThreshold(double epsilon) {
        for (int i = 0; i < convergenceCurve.size(); i++) {
            if (convergenceCurve.get(i) <= epsilon) {
                int iteration = i + 1;
                double normalized = totalIterations == 0
                        ? 0.0
                        : (double) iteration / totalIterations;

                return new ThresholdHit(iteration, normalized);
            }
        }

        return new ThresholdHit(-1, -1.0);
    }
}

