package edu.swarmintelligence.mayfly;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

@DisplayName("AgentInteractionAnalyzer")
class AgentInteractionAnalyzerTest {

    private final AgentInteractionAnalyzer analyzer = new AgentInteractionAnalyzer();

    @Nested
    @DisplayName("event handling")
    class EventHandling {

        @Test
        void shouldCountNuptialDanceUpdates() {
            Mayfly male = mayfly(new double[]{0.0, 0.0}, 1.0);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.MaleUpdated(male, true, 2.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 1.0, java.util.List.of(male)));

            AgentInteractionResult result = result();

            assertThat(result.nuptialDanceCount()).isEqualTo(1);
            assertThat(result.interactionHistogram()).containsEntry("NUPTIAL_DANCE", 1);
        }

        @Test
        void shouldCountMaleAttractionUpdatesWithoutNuptialDance() {
            Mayfly male = mayfly(new double[]{1.0, 1.0}, 2.0);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.MaleUpdated(male, false, 3.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 2.0, java.util.List.of(male)));

            AgentInteractionResult result = result();

            assertThat(result.attractionCount()).isEqualTo(1);
            assertThat(result.interactionHistogram()).containsEntry("MALE_ATTRACTION", 1);
        }

        @Test
        void shouldCalculateFemaleAttractionRatePerIteration() {
            Mayfly female1 = mayfly(new double[]{0.0, 0.0}, 1.0);
            Mayfly female2 = mayfly(new double[]{1.0, 1.0}, 2.0);
            Mayfly male = mayfly(new double[]{2.0, 2.0}, 0.5);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.FemaleUpdated(female1, male, true, 2.0));
            analyzer.onEvent(new MayflyEvent.FemaleUpdated(female2, male, false, 3.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 1.0, java.util.List.of(female1, female2)));

            AgentInteractionResult result = result();

            assertThat(result.femaleAttractionRate()).containsEntry(1, 0.5);
            assertThat(result.interactionHistogram()).containsEntry("FEMALE_ATTRACTION", 1);
            assertThat(result.interactionHistogram()).containsEntry("FEMALE_RANDOM_WALK", 1);
        }

        @Test
        void shouldCalculateMeanPairDistance() {
            Mayfly female = mayfly(new double[]{0.0, 0.0}, 1.0);
            Mayfly male = mayfly(new double[]{3.0, 4.0}, 0.5);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.FemaleUpdated(female, male, true, 2.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 1.0, java.util.List.of(female, male)));

            AgentInteractionResult result = result();

            assertThat(result.meanPairDistance()).containsEntry(1, 5.0);
        }

        @Test
        void shouldCalculateMeanPairFitnessGap() {
            Mayfly female = mayfly(new double[]{0.0, 0.0}, 7.5);
            Mayfly male = mayfly(new double[]{1.0, 1.0}, 2.0);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.FemaleUpdated(female, male, true, 8.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 2.0, java.util.List.of(female, male)));

            AgentInteractionResult result = result();

            assertThat(result.pairFitnessGap()).containsEntry(1, 5.5);
        }

        @Test
        void shouldStoreZeroMetricsWhenNoFemaleUpdatesOccurInIteration() {
            Mayfly male = mayfly(new double[]{1.0, 1.0}, 1.0);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.MaleUpdated(male, true, 2.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 1.0, java.util.List.of(male)));

            AgentInteractionResult result = result();

            assertThat(result.femaleAttractionRate()).containsEntry(1, 0.0);
            assertThat(result.meanPairDistance()).containsEntry(1, 0.0);
            assertThat(result.pairFitnessGap()).containsEntry(1, 0.0);
        }

        @Test
        void shouldIgnoreUnrelatedEvents() {
            Mayfly agent = mayfly(new double[]{0.0, 0.0}, 1.0);

            analyzer.onEvent(new MayflyEvent.PbestUpdated(agent, 2.0, 1.0));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, 2.0, 1.0));
            analyzer.onEvent(new MayflyEvent.RunCompleted(new MayflyResult(new double[]{0.0, 0.0}, 1.0)));

            AgentInteractionResult result = result();

            assertThat(result.nuptialDanceCount()).isZero();
            assertThat(result.attractionCount()).isZero();
            assertThat(result.femaleAttractionRate()).isEmpty();
            assertThat(result.meanPairDistance()).isEmpty();
            assertThat(result.pairFitnessGap()).isEmpty();
        }
    }

    @Nested
    @DisplayName("numeric stability")
    class NumericStability {

        @Test
        void shouldHandleZeroDistancePairs() {
            Mayfly female = mayfly(new double[]{2.0, 2.0}, 1.0);
            Mayfly male = mayfly(new double[]{2.0, 2.0}, 1.0);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.FemaleUpdated(female, male, true, 1.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 1.0, java.util.List.of(female, male)));

            AgentInteractionResult result = result();

            assertThat(result.meanPairDistance()).containsEntry(1, 0.0);
            assertThat(result.pairFitnessGap()).containsEntry(1, 0.0);
        }
    }

    private AgentInteractionResult result() {
        return (AgentInteractionResult) analyzer.result();
    }

