package edu.swarmintelligence.mayfly;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

@DisplayName("GlobalMemoryAnalyzer")
class GlobalMemoryAnalyzerTest {

    private final GlobalMemoryAnalyzer analyzer = new GlobalMemoryAnalyzer();

    @Nested
    @DisplayName("gbest trajectory")
    class GbestTrajectory {

        @Test
        void shouldStoreGbestFitnessPerCompletedIteration() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(2, 0.8));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(2, 3.0, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.gbestTrajectory()).containsExactly(5.0, 3.0);
        }

        @Test
        void shouldReturnFirstHittingIterationForGivenThreshold() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(2, 0.8));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(2, 0.01, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(3, 0.7));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(3, 0.0005, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.firstHittingIteration(1e-3)).isEqualTo(3);
        }

        @Test
        void shouldReturnMinusOneIfThresholdIsNeverReached() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(2, 0.8));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(2, 2.0, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.firstHittingIteration(1e-3)).isEqualTo(-1);
        }
    }

    @Nested
    @DisplayName("gbest updates")
    class GbestUpdates {

        @Test
        void shouldCountGbestUpdates() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, 10.0, 5.0));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.OFFSPRING, 5.0, 2.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 2.0, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.gbestUpdateCount()).isEqualTo(2);
        }

        @Test
        void shouldCalculateUpdateSourceDistribution() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, 10.0, 5.0));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, 5.0, 4.0));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.OFFSPRING, 4.0, 2.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 2.0, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.gbestUpdateSourceDistribution())
                    .containsEntry(UpdateSource.MALE, 2.0 / 3.0)
                    .containsEntry(UpdateSource.OFFSPRING, 1.0 / 3.0)
                    .containsEntry(UpdateSource.FEMALE, 0.0);
        }

        @Test
        void shouldReturnZeroSourceDistributionWhenNoUpdatesExist() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 10.0, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.gbestUpdateCount()).isZero();
            assertThat(result.gbestUpdateSourceDistribution())
                    .containsEntry(UpdateSource.MALE, 0.0)
                    .containsEntry(UpdateSource.FEMALE, 0.0)
                    .containsEntry(UpdateSource.OFFSPRING, 0.0);
        }

        @Test
        void shouldAccumulateImprovementDeltaPerIteration() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, 10.0, 7.0));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.FEMALE, 7.0, 5.5));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 5.5, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.improvementDelta()).containsEntry(1, 4.5);
        }
    }

    @Nested
    @DisplayName("stagnation")
    class Stagnation {

        @Test
        void shouldDetectStagnationStreaksWithoutGbestUpdates() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, 10.0, 5.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(2, 0.8));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(2, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(3, 0.7));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(3, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(4, 0.6));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.OFFSPRING, 5.0, 3.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(4, 3.0, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.stagnationStreaks()).containsExactly(2);
        }

        @Test
        void shouldCloseFinalStagnationStreakOnRunCompleted() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.IterationStarted(2, 0.8));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(2, 5.0, java.util.List.of()));

            analyzer.onEvent(new MayflyEvent.RunCompleted(new MayflyResult(new double[]{0.0}, 5.0)));

            GlobalMemoryResult result = result();

            assertThat(result.stagnationStreaks()).containsExactly(2);
        }
    }

    @Nested
    @DisplayName("numeric stability")
    class NumericStability {

        @Test
        void shouldIgnoreNonFiniteImprovementDelta() {
            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, Double.POSITIVE_INFINITY, 1.0));
            analyzer.onEvent(new MayflyEvent.IterationCompleted(1, 1.0, java.util.List.of()));

            GlobalMemoryResult result = result();

            assertThat(result.gbestUpdateCount()).isEqualTo(1);
            assertThat(result.improvementDelta()).containsEntry(1, 0.0);
        }
    }

    private GlobalMemoryResult result() {
        return (GlobalMemoryResult) analyzer.result();
    }
}

