package edu.swarmintelligence.mayfly;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

@DisplayName("LocalMemoryAnalyzer")
class LocalMemoryAnalyzerTest {

    private final LocalMemoryAnalyzer analyzer = new LocalMemoryAnalyzer();

    @Nested
    @DisplayName("pbest updates")
    class PbestUpdates {

        @Test
        void shouldCountPbestUpdatesPerAgent() {
            Mayfly agent = mayfly(new double[]{1.0, 1.0}, 5.0);

            analyzer.onEvent(new MayflyEvent.PbestUpdated(agent, 10.0, 5.0));
            analyzer.onEvent(new MayflyEvent.PbestUpdated(agent, 5.0, 2.5));

            LocalMemoryResult result = result();

            assertThat(result.pbestUpdateCountPerAgent())
                    .containsEntry(agent, 2);
        }

        @Test
        void shouldCalculateMeanRelativePbestImprovement() {
            Mayfly first = mayfly(new double[]{1.0, 1.0}, 5.0);
            Mayfly second = mayfly(new double[]{2.0, 2.0}, 4.0);

            analyzer.onEvent(new MayflyEvent.PbestUpdated(first, 10.0, 5.0));
            analyzer.onEvent(new MayflyEvent.PbestUpdated(second, 8.0, 4.0));

            LocalMemoryResult result = result();

            assertThat(result.meanPbestImprovement())
                    .isCloseTo(0.5, within(1e-12));
        }

        @Test
        void shouldReturnZeroMeanImprovementWhenNoValidPbestUpdatesExist() {
            Mayfly agent = mayfly(new double[]{1.0, 1.0}, 5.0);

            analyzer.onEvent(new MayflyEvent.PbestUpdated(agent, Double.POSITIVE_INFINITY, 5.0));
            analyzer.onEvent(new MayflyEvent.PbestUpdated(agent, 0.0, 0.0));

            LocalMemoryResult result = result();

            assertThat(result.meanPbestImprovement()).isZero();
        }
    }

    @Nested
    @DisplayName("pbest diversity")
    class PbestDiversity {

        @Test
        void shouldCalculatePbestPositionDiversityPerIteration() {
            Mayfly first = mayfly(new double[]{0.0, 0.0}, 1.0);
            Mayfly second = mayfly(new double[]{2.0, 2.0}, 2.0);

            analyzer.onEvent(new MayflyEvent.IterationCompleted(
                    1,
                    1.0,
                    List.of(first, second)
            ));

            LocalMemoryResult result = result();

            assertThat(result.pbestPositionDiversity())
                    .containsEntry(1, 1.0);
        }

        @Test
        void shouldReturnZeroDiversityForEmptyPopulation() {
            analyzer.onEvent(new MayflyEvent.IterationCompleted(
                    1,
                    1.0,
                    List.of()
            ));

            LocalMemoryResult result = result();

            assertThat(result.pbestPositionDiversity())
                    .containsEntry(1, 0.0);
        }

        @Test
        void shouldReturnZeroDiversityForIdenticalPbestPositions() {
            Mayfly first = mayfly(new double[]{3.0, 3.0}, 1.0);
            Mayfly second = mayfly(new double[]{3.0, 3.0}, 2.0);

            analyzer.onEvent(new MayflyEvent.IterationCompleted(
                    1,
                    1.0,
                    List.of(first, second)
            ));

            LocalMemoryResult result = result();

            assertThat(result.pbestPositionDiversity())
                    .containsEntry(1, 0.0);
        }
    }

    @Nested
    @DisplayName("pbest fitness distribution")
    class PbestFitnessDistribution {

        @Test
        void shouldCalculatePbestFitnessDistributionPerIteration() {
            Mayfly first = mayfly(new double[]{0.0}, 1.0);
            Mayfly second = mayfly(new double[]{1.0}, 2.0);
            Mayfly third = mayfly(new double[]{2.0}, 3.0);
            Mayfly fourth = mayfly(new double[]{3.0}, 4.0);

            analyzer.onEvent(new MayflyEvent.IterationCompleted(
                    1,
                    1.0,
                    List.of(first, second, third, fourth)
            ));

            LocalMemoryResult result = result();
            FitnessDistribution distribution = result.pbestFitnessDistribution().get(1);

            assertThat(distribution.min()).isEqualTo(1.0);
            assertThat(distribution.q25()).isCloseTo(1.75, within(1e-12));
            assertThat(distribution.median()).isCloseTo(2.5, within(1e-12));
            assertThat(distribution.q75()).isCloseTo(3.25, within(1e-12));
            assertThat(distribution.max()).isEqualTo(4.0);
        }

        @Test
        void shouldReturnZeroDistributionForEmptyPopulation() {
            analyzer.onEvent(new MayflyEvent.IterationCompleted(
                    1,
                    1.0,
                    List.of()
            ));

            LocalMemoryResult result = result();
            FitnessDistribution distribution = result.pbestFitnessDistribution().get(1);

            assertThat(distribution.min()).isZero();
            assertThat(distribution.q25()).isZero();
            assertThat(distribution.median()).isZero();
            assertThat(distribution.q75()).isZero();
            assertThat(distribution.max()).isZero();
        }
    }

    @Nested
    @DisplayName("event filtering")
    class EventFiltering {

        @Test
        void shouldIgnoreUnrelatedEvents() {
            Mayfly agent = mayfly(new double[]{0.0}, 1.0);

            analyzer.onEvent(new MayflyEvent.IterationStarted(1, 0.9));
            analyzer.onEvent(new MayflyEvent.MaleUpdated(agent, true, 2.0));
            analyzer.onEvent(new MayflyEvent.GbestUpdated(UpdateSource.MALE, 2.0, 1.0));
            analyzer.onEvent(new MayflyEvent.RunCompleted(new MayflyResult(new double[]{0.0}, 1.0)));

            LocalMemoryResult result = result();

            assertThat(result.pbestUpdateCountPerAgent()).isEmpty();
            assertThat(result.meanPbestImprovement()).isZero();
            assertThat(result.pbestPositionDiversity()).isEmpty();
            assertThat(result.pbestFitnessDistribution()).isEmpty();
        }
    }

    private LocalMemoryResult result() {
        return (LocalMemoryResult) analyzer.result();
    }

    private Mayfly mayfly(double[] pbestPosition, double pbestFitness) {
        Mayfly mayfly = new Mayfly(pbestPosition.length);

        System.arraycopy(pbestPosition, 0, mayfly.pos, 0, pbestPosition.length);
        System.arraycopy(pbestPosition, 0, mayfly.pbestPos, 0, pbestPosition.length);

        mayfly.fitness = pbestFitness;
        mayfly.pbestFitness = pbestFitness;

        return mayfly;
    }
}

