package edu.swarmintelligence.mayfly;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

@DisplayName("ConvergenceAnalyzer")
class ConvergenceAnalyzerTest {

    private ConvergenceAnalyzer analyzer;

    @BeforeEach
    void setUp() {
        analyzer = new ConvergenceAnalyzer();
    }

    @Nested
    @DisplayName("convergence curve")
    class ConvergenceCurve {

        @Test
        void shouldStoreBestFitnessPerCompletedIteration() {
            analyzer.onEvent(iterationCompleted(1, 10.0, List.of()));
            analyzer.onEvent(iterationCompleted(2, 5.0, List.of()));
            analyzer.onEvent(iterationCompleted(3, 1.0, List.of()));

            ConvergenceResult result = result();

            assertThat(result.convergenceCurve())
                    .containsExactly(10.0, 5.0, 1.0);
        }

        @Test
        void shouldReturnThresholdHitWithNormalizedIteration() {
            analyzer.onEvent(iterationCompleted(1, 10.0, List.of()));
            analyzer.onEvent(iterationCompleted(2, 0.0005, List.of()));
            analyzer.onEvent(iterationCompleted(3, 0.0001, List.of()));

            ConvergenceResult result = result();
            ThresholdHit hit = result.iterationsToThreshold(1e-3);

            assertThat(hit.iteration()).isEqualTo(2);
            assertThat(hit.normalizedIteration()).isCloseTo(2.0 / 3.0, within(1e-12));
        }

        @Test
        void shouldReturnMinusOneWhenThresholdIsNeverReached() {
            analyzer.onEvent(iterationCompleted(1, 10.0, List.of()));
            analyzer.onEvent(iterationCompleted(2, 5.0, List.of()));
            analyzer.onEvent(iterationCompleted(3, 1.0, List.of()));

            ConvergenceResult result = result();
            ThresholdHit hit = result.iterationsToThreshold(1e-3);

            assertThat(hit.iteration()).isEqualTo(-1);
            assertThat(hit.normalizedIteration()).isEqualTo(-1.0);
        }
    }

    @Nested
    @DisplayName("population diversity")
    class PopulationDiversity {

        @Test
        void shouldCalculateMeanPairwisePopulationDistance() {
            Mayfly first = mayfly(new double[]{0.0, 0.0}, 1.0);
            Mayfly second = mayfly(new double[]{3.0, 4.0}, 2.0);

            analyzer.onEvent(iterationCompleted(1, 1.0, List.of(first, second)));

            ConvergenceResult result = result();

            assertThat(result.populationDiversity())
                    .containsEntry(1, 5.0);
        }

        @Test
        void shouldReturnZeroDiversityForEmptyPopulation() {
            analyzer.onEvent(iterationCompleted(1, 1.0, List.of()));

            ConvergenceResult result = result();

            assertThat(result.populationDiversity())
                    .containsEntry(1, 0.0);
        }

        @Test
        void shouldReturnZeroDiversityForSingleAgentPopulation() {
            Mayfly onlyAgent = mayfly(new double[]{1.0, 1.0}, 1.0);

            analyzer.onEvent(iterationCompleted(1, 1.0, List.of(onlyAgent)));

            ConvergenceResult result = result();

            assertThat(result.populationDiversity())
                    .containsEntry(1, 0.0);
        }
    }

    @Nested
    @DisplayName("plateau detection")
    class PlateauDetection {

        @Test
        void shouldDetectPlateauSegmentWithDefaultMinimumLength() {
            for (int iteration = 1; iteration <= 6; iteration++) {
                analyzer.onEvent(iterationCompleted(iteration, 5.0, List.of()));
            }

            analyzer.onEvent(new MayflyEvent.RunCompleted(new MayflyResult(new double[]{0.0}, 5.0)));

            ConvergenceResult result = result();

            assertThat(result.plateauSegments())
                    .containsExactly(new PlateauSegment(1, 6, 6));
        }

        @Test
        void shouldNotDetectPlateauBelowMinimumLength() {
            analyzer.onEvent(iterationCompleted(1, 5.0, List.of()));
            analyzer.onEvent(iterationCompleted(2, 5.0, List.of()));
            analyzer.onEvent(iterationCompleted(3, 5.0, List.of()));
            analyzer.onEvent(new MayflyEvent.RunCompleted(new MayflyResult(new double[]{0.0}, 5.0)));

            ConvergenceResult result = result();

            assertThat(result.plateauSegments()).isEmpty();
        }

        @Test
        void shouldUseConfiguredPlateauEpsilon() {
            analyzer = new ConvergenceAnalyzer(2, 0.1, 0.5);

            analyzer.onEvent(iterationCompleted(1, 5.00, List.of()));
            analyzer.onEvent(iterationCompleted(2, 4.95, List.of()));
            analyzer.onEvent(iterationCompleted(3, 4.90, List.of()));
            analyzer.onEvent(new MayflyEvent.RunCompleted(new MayflyResult(new double[]{0.0}, 4.90)));

            ConvergenceResult result = result();

            assertThat(result.plateauSegments())
                    .containsExactly(new PlateauSegment(1, 3, 3));
        }
    }

    @Nested
    @DisplayName("convergence rate")
    class ConvergenceRate {

        @Test
        void shouldEstimateNegativeRateForImprovingFitnessCurve() {
            analyzer = new ConvergenceAnalyzer(5, 1e-12, 1.0);

            analyzer.onEvent(iterationCompleted(1, 100.0, List.of()));
            analyzer.onEvent(iterationCompleted(2, 10.0, List.of()));
            analyzer.onEvent(iterationCompleted(3, 1.0, List.of()));

            ConvergenceResult result = result();

            assertThat(result.convergenceRateEstimate()).isLessThan(0.0);
        }

        @Test
        void shouldReturnZeroRateForSingleSample() {
            analyzer.onEvent(iterationCompleted(1, 1.0, List.of()));

            ConvergenceResult result = result();

            assertThat(result.convergenceRateEstimate()).isZero();
        }
    }

    @Nested
    @DisplayName("numeric stability")
    class NumericStability {

        @Test
        void shouldIgnoreNonFiniteValuesInRateEstimate() {
            analyzer = new ConvergenceAnalyzer(5, 1e-12, 1.0);

            analyzer.onEvent(iterationCompleted(1, Double.NaN, List.of()));
            analyzer.onEvent(iterationCompleted(2, 10.0, List.of()));
            analyzer.onEvent(iterationCompleted(3, 1.0, List.of()));

            ConvergenceResult result = result();

            assertThat(result.convergenceRateEstimate()).isFinite();
        }

        @Test
        void shouldHandleZeroFitnessInRateEstimate() {
            analyzer = new ConvergenceAnalyzer(5, 1e-12, 1.0);

            analyzer.onEvent(iterationCompleted(1, 1.0, List.of()));
            analyzer.onEvent(iterationCompleted(2, 0.0, List.of()));
            analyzer.onEvent(iterationCompleted(3, 0.0, List.of()));

            ConvergenceResult result = result();

            assertThat(result.convergenceRateEstimate()).isFinite();
        }
    }

    private ConvergenceResult result() {
        return (ConvergenceResult) analyzer.result();
    }

    private MayflyEvent.IterationCompleted iterationCompleted(
            int iteration,
            double gbestFitness,
            List<Mayfly> survivors
    ) {
        return new MayflyEvent.IterationCompleted(iteration, gbestFitness, survivors);
    }

    private Mayfly mayfly(double[] position, double fitness) {
        Mayfly mayfly = new Mayfly(position.length);

        System.arraycopy(position, 0, mayfly.pos, 0, position.length);
        System.arraycopy(position, 0, mayfly.pbestPos, 0, position.length);

        mayfly.fitness = fitness;
        mayfly.pbestFitness = fitness;

        return mayfly;
    }
}

