package edu.swarmintelligence.mayfly;

import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.ValueSource;
import org.junit.jupiter.params.provider.Arguments;

import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

@DisplayName("Parameterized analytics tests")
class ParameterizedAnalyticsTest {

    private static MayflyConfig smallConfig;

    @BeforeAll
    static void setUpFixture() {
        smallConfig = new MayflyConfig(
                3,
                -5.0,
                5.0,
                6,
                25,
                0.9,
                0.4,
                1.0,
                1.5,
                1.5,
                2.0,
                0.1,
                0.1,
                0.05
        );
    }

    @ParameterizedTest(name = "seed {0} produces deterministic Mayfly results")
    @ValueSource(longs = {1L, 42L, 1234L})
    void shouldProduceDeterministicResultsForSameSeed(long seed) {
        MayflyAlgorithm firstAlgorithm = new MayflyAlgorithm();
        MayflyAlgorithm secondAlgorithm = new MayflyAlgorithm();

        MayflyResult first = firstAlgorithm.run(smallConfig, seed);
        MayflyResult second = secondAlgorithm.run(smallConfig, seed);

        assertThat(first.gbestFitness()).isEqualTo(second.gbestFitness());
        assertThat(first.gbestPosition()).containsExactly(second.gbestPosition());
    }

    @ParameterizedTest(name = "epsilon {0} is first reached at iteration {1}")
    @CsvSource({
            "10.0, 1",
            "1.0, 2",
            "0.1, 3",
            "0.0001, -1"
    })
    void shouldFindFirstHittingIterationForDifferentThresholds(double epsilon, int expectedIteration) {
        GlobalMemoryResult result = new GlobalMemoryResult(
                List.of(5.0, 0.5, 0.05),
                0,
                Map.of(
                        UpdateSource.MALE, 0.0,
                        UpdateSource.FEMALE, 0.0,
                        UpdateSource.OFFSPRING, 0.0
                ),
                Map.of(),
                List.of()
        );

        assertThat(result.firstHittingIteration(epsilon)).isEqualTo(expectedIteration);
    }

    @ParameterizedTest(name = "invalid config case: {0}")
    @MethodSource("invalidConfigs")
    void shouldRejectInvalidMayflyConfigurations(
            String description,
            int dimensions,
            double lowerBound,
            double upperBound,
            int populationSize,
            int maxIterations,
            double wMax,
            double wMin,
            double a1,
            double a2,
            double a3,
            double beta,
            double danceCoeff,
            double flightCoeff,
            double mutationStdDev
    ) {
        assertThatThrownBy(() -> new MayflyConfig(
                dimensions,
                lowerBound,
                upperBound,
                populationSize,
                maxIterations,
                wMax,
                wMin,
                a1,
                a2,
                a3,
                beta,
                danceCoeff,
                flightCoeff,
                mutationStdDev
        )).isInstanceOf(IllegalArgumentException.class);
    }

    private static Stream<Arguments> invalidConfigs() {
        return Stream.of(
                Arguments.of("dimensions must be positive",
                        0, -5.0, 5.0, 6, 25, 0.9, 0.4,
                        1.0, 1.5, 1.5, 2.0, 0.1, 0.1, 0.05),

                Arguments.of("lowerBound must be smaller than upperBound",
                        3, 5.0, 5.0, 6, 25, 0.9, 0.4,
                        1.0, 1.5, 1.5, 2.0, 0.1, 0.1, 0.05),

                Arguments.of("populationSize must be greater than one",
