package edu.swarmintelligence.mayfly;

// AI-generated: ChatGPT, 2026-05-20, task 3.1

import com.tngtech.jgiven.Stage;
import com.tngtech.jgiven.annotation.ExpectedScenarioState;
import com.tngtech.jgiven.annotation.ScenarioState.Resolution;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

public class ThenAnalyticsReport extends Stage<ThenAnalyticsReport> {

    @ExpectedScenarioState(resolution = Resolution.NAME)
    MayflyResult result;

    @ExpectedScenarioState(resolution = Resolution.NAME)
    MayflyResult secondResult;

    @ExpectedScenarioState
    AnalyticsReport report;

    @ExpectedScenarioState
    double femaleAttractionThreshold;

    @ExpectedScenarioState
    ConvergenceResult artificialConvergenceResult;

    public ThenAnalyticsReport the_final_gbest_is_reproducible() {
        assertThat(result.gbestFitness()).isEqualTo(secondResult.gbestFitness());
        assertThat(result.gbestPosition()).containsExactly(secondResult.gbestPosition());

        return self();
    }

    public ThenAnalyticsReport the_final_ackley_value_is_below_$(double threshold) {
        assertThat(result.gbestFitness()).isLessThan(threshold);

        return self();
    }

    public ThenAnalyticsReport the_gbest_trajectory_is_monotonically_non_increasing() {
        GlobalMemoryResult globalMemoryResult = globalMemoryResult();
        List<Double> trajectory = globalMemoryResult.gbestTrajectory();

        assertThat(trajectory).isNotEmpty();

        for (int i = 1; i < trajectory.size(); i++) {
            assertThat(trajectory.get(i))
                    .isLessThanOrEqualTo(trajectory.get(i - 1));
        }

        return self();
    }

    public ThenAnalyticsReport the_average_female_attraction_rate_is_above_the_threshold() {
        AgentInteractionResult agentInteractionResult = agentInteractionResult();

        double averageRate = agentInteractionResult.femaleAttractionRate()
                .values()
                .stream()
                .mapToDouble(Double::doubleValue)
                .average()
                .orElse(0.0);

        assertThat(averageRate).isGreaterThan(femaleAttractionThreshold);

        return self();
    }

    public ThenAnalyticsReport every_tracked_agent_has_at_least_one_pbest_update() {
        LocalMemoryResult localMemoryResult = localMemoryResult();

        assertThat(localMemoryResult.pbestUpdateCountPerAgent())
                .isNotEmpty();

        assertThat(localMemoryResult.pbestUpdateCountPerAgent().values())
                .allSatisfy(count -> assertThat(count).isGreaterThanOrEqualTo(1));

        return self();
    }

    public ThenAnalyticsReport exactly_one_plateau_is_detected() {
        assertThat(artificialConvergenceResult.plateauSegments())
                .hasSize(1);

        return self();
    }

    private AgentInteractionResult agentInteractionResult() {
        return (AgentInteractionResult) report.byAnalyzer().get("agent-interaction");
    }

    private GlobalMemoryResult globalMemoryResult() {
        return (GlobalMemoryResult) report.byAnalyzer().get("global-memory");
    }

    private LocalMemoryResult localMemoryResult() {
        return (LocalMemoryResult) report.byAnalyzer().get("local-memory");
    }
}

